(function(root){'use strict';
 function create(view,H){const{svg,label,line}=H,s=H.diagram(view,'Синаптический контакт: мембраны, везикулы, рецепторы или щелевые контакты');return(kind,result,time)=>{const p=result.trace.reduce((a,b)=>Math.abs(b.t-time)<Math.abs(a.t-time)?b:a);s.replaceChildren();if(kind==='chemical'){s.append(svg('path',{d:'M235 15 L235 55 C120 65 108 139 154 172 Q230 204 379 174 C440 152 427 76 335 55 L335 15',fill:'#d9e6dc',stroke:'#6e8d79','stroke-width':3}),svg('path',{d:'M155 222 Q260 192 375 222 L398 285 L129 285 Z',fill:'#e8ded1',stroke:'#a79070','stroke-width':3}),svg('path',{d:'M173 180 Q265 197 362 180',fill:'none',stroke:'#527f68','stroke-width':5}),svg('path',{d:'M178 214 Q270 202 356 214',fill:'none',stroke:'#a79070','stroke-width':5}));const vesicles=Math.round(12*p.reserve);for(let i=0;i<vesicles;i++){const x=189+(i%4)*48,y=80+Math.floor(i/4)*33;s.append(svg('circle',{cx:x,cy:y,r:12,fill:'#f4e5bd',stroke:'#b6955b','stroke-width':2}));for(let j=0;j<3;j++)s.append(svg('circle',{cx:x-4+j*4,cy:y+(j%2)*4-2,r:2,fill:'#a88244'}));}for(let i=0;i<6;i++){const x=190+i*28;line(s,x,207,x,226,p.g>.5?'#bd7548':'#708c7a',5);}const dots=Math.min(26,Math.round(p.g*9));for(let i=0;i<dots;i++)s.append(svg('circle',{cx:173+(i*31%190),cy:190+(i*7%16),r:2.2,fill:'#bd7548'}));s.append(svg('ellipse',{cx:364,cy:110,rx:24,ry:11,fill:'#d2a17c',stroke:'#a77854'}));for(let j=0;j<4;j++)line(s,350+j*8,104,355+j*8,116,'#a77854',1);label(s,30,75,'Везикулы');line(s,105,80,174,93,'#8b998c',1);label(s,440,123,'Терминаль');label(s,435,200,'Щель');label(s,431,249,'Постсинаптическая');label(s,431,267,'мембрана');}else{for(const x of[90,365])s.append(svg('path',{d:`M${x} 55 Q${x+80} 18 ${x+175} 60 L${x+175} 235 Q${x+85} 270 ${x} 235 Z`,fill:'#dbe6dc',stroke:'#799080','stroke-width':3}));for(let i=0;i<5;i++){const y=92+i*25;line(s,265,y,365,y,'#bd9971',11);line(s,265,y,365,y,'#f6e9cf',3);}label(s,115,36,'Клетка 1');label(s,405,36,'Клетка 2');label(s,110,287,'V1 = '+p.v1.toFixed(1)+' мВ');label(s,391,287,'V2 = '+p.v2.toFixed(1)+' мВ');label(s,263,65,'Коннексоны');}label(s,20,326,'t = '+p.t.toFixed(1)+' мс · размеры структур увеличены, масштаб условный');s.setAttribute('viewBox','0 0 640 345');s.dataset.time=p.t;s.dataset.kind=kind;};}
 root.SynapseView={create};
})(globalThis);
